```javascript
import { gsap } from 'gsap';
import { uv, mix, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  // === CONSTANTS ===
  const CARD_W = 2.4;
  const CARD_H = 3.2;
  const PADDING = 0.5;
  const HEADER_H = 0.08;
  const FEATURE_H = 0.375;
  const FEATURE_SEP = 0.006;
  const CTA_W = 1.4;
  const CTA_H = 0.36;
  const CTA_BOTTOM = 0.5;

  // === COLORS ===
  const colors = {
    background: new Color('#0b0b10'),
    surface: new Color('#16161d'),
    border: new Color('#2a2a33'),
    separator: new Color('#23232b'),
    accent: new Color('#ff2a38'),
    gradTop: new Color('#ff4450'),
    gradBot: new Color('#c1121f'),
    ink: new Color('#16161d'),
    paper: new Color('#e8ecf2'),
  };

  const timelines = [];
  const toDispose = [];
  const textMeshes = [];

  const root = new Group();

  // === STAGE BACKDROP ===
  {
    const geom = new PlaneGeometry(7, 6);
    const mat = new THREE.MeshBasicNodeMaterial();
    const uvNode = uv();
    mat.colorNode = mix(
      uniform(colors.gradBot),
      uniform(colors.gradTop),
      uvNode.y
    );
    const mesh = new Mesh(geom, mat);
    mesh.position.z = -2.5;
    root.add(mesh);
    toDispose.push(geom, mat);
  }

  // === CARD GROUP ===
  const cardGroup = new Group();
  root.add(cardGroup);

  // Card base
  {
    const geom = new PlaneGeometry(CARD_W, CARD_H);
    const mat = new THREE.MeshStandardNodeMaterial({
      color: colors.surface,
      roughness: 0.5,
      metalness: 0,
    });
    const mesh = new Mesh(geom, mat);
    cardGroup.add(mesh);
    toDispose.push(geom, mat);
  }

  // Card border
  {
    const geom = new PlaneGeometry(CARD_W + 0.012, CARD_H + 0.012);
    const mat = new THREE.MeshBasicNodeMaterial({ color: colors.border });
    const mesh = new Mesh(geom, mat);
    mesh.position.z = -0.001;
    cardGroup.add(mesh);
    toDispose.push(geom, mat);
  }

  // Header strip (metal)
  {
    const geom = new PlaneGeometry(CARD_W, HEADER_H);
    const mat = new THREE.MeshStandardNodeMaterial({
      color: colors.surface,
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2,
    });
    mat.anisotropy = 0.6;
    const mesh = new Mesh(geom, mat);
    mesh.position.y = CARD_H / 2 - HEADER_H / 2;
    mesh.position.z = 0.001;
    cardGroup.add(mesh);
    toDispose.push(geom, mat);
  }

  // === TEXT ELEMENTS ===

  // Tier name
  {
    const text = ctx.fontAtlas.createText('ATELIER RESERVE', {
      fontSize: 20,
      color: colors.paper,
      align: 'left',
    });
    text.position.set(-CARD_W / 2 + PADDING, CARD_H / 2 - HEADER_H - 0.2, 0.002);
    cardGroup.add(text);
    textMeshes.push(text);
  }

  // Price
  {
    const text = ctx.fontAtlas.createText('$480', {
      fontSize: 62,
      color: colors.paper,
      align: 'left',
    });
    text.position.set(-CARD_W / 2 + PADDING, CARD_H / 2 - HEADER_H - 0.52, 0.002);
    cardGroup.add(text);
    textMeshes.push(text);
  }

  // Caption
  {
    const text = ctx.fontAtlas.createText('PER MONTH, BILLED ANNUALLY', {
      fontSize: 9,
      color: colors.paper,
      align: 'left',
    });
    text.position.set(-CARD_W / 2 + PADDING, CARD_H / 2 - HEADER_H - 0.68, 0.002);
    cardGroup.add(text);
    textMeshes.push(text);
  }

  // Features
  const features = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing',
  ];

  const featureTexts = [];
  const featureStartY = CARD_H / 2 - HEADER_H - 1.3;

  for (let i = 0; i < features.length; i++) {
    const featureY = featureStartY - i * (FEATURE_H + FEATURE_SEP);

    const text = ctx.fontAtlas.createText(features[i], {
      fontSize: 13,
      color: colors.paper,
      align: 'left',
    });
    text.position.set(-CARD_W / 2 + PADDING, featureY, 0.002);
    cardGroup.add(text);
    featureTexts.push({ mesh: text, initialY: featureY });
    textMeshes.push(text);

    // Separator (except after last feature)
    if (i < features.length - 1) {
      const geom = new PlaneGeometry(CARD_W - 2 * PADDING, FEATURE_SEP);
      const mat = new THREE.MeshBasicNodeMaterial({ color: colors.separator });
      const sep = new Mesh(geom, mat);
      sep.position.y = featureY - FEATURE_H / 2;
      sep.position.z = 0.001;
      cardGroup.add(sep);
      toDispose.push(geom, mat);
    }
  }

  // === CTA BUTTON ===
  const ctaGroup = new Group();
  cardGroup.add(ctaGroup);

  const ctaY = -CARD_H / 2 + CTA_BOTTOM + CTA_H / 2;
  ctaGroup.position.y = ctaY;

  // CTA background (with gradient)
  {
    const geom = new PlaneGeometry(CTA_W, CTA_H);
    const mat = new THREE.MeshStandardNodeMaterial({
      emissive: colors.accent,
      emissiveIntensity: 1.5,
      roughness: 0.5,
      metalness: 0,
    });

    const uvNode = uv();
    mat.colorNode = mix(
      uniform(colors.gradBot),
      uniform(colors.gradTop),
      uvNode.y
    );

    const mesh = new Mesh(geom, mat);
    mesh.position.z = 0.001;
    ctaGroup.add(mesh);
    toDispose.push(geom, mat);
  }

  // CTA label
  {
    const text = ctx.fontAtlas.createText('JOIN THE RESERVE', {
      fontSize: 13,
      color: colors.ink,
      align: 'center',
    });
    text.position.z = 0.002;
    ctaGroup.add(text);
    textMeshes.push(text);
  }

  // === LIGHTING ===
  {
    const light = new THREE.DirectionalLight(0xffffff, 1.2);
    light.position.set(2, 2, 2);
    root.add(light);
  }

  {
    const light = new THREE.DirectionalLight(colors.accent, 0.8);
    light.position.set(-2, -1, 1);
    root.add(light);
  }

  // === ANIMATIONS ===

  // Weighted settle: card scale 1.04 → 1.0
  cardGroup.scale.set(1.04, 1.04, 1.04);
  const settleTl = gsap.timeline();
  timelines.push(settleTl);
  settleTl.to(cardGroup.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
  });

  // Feature stagger fade-up
  const staggerTl = gsap.timeline({ delay: 0.1 });
  timelines.push(staggerTl);

  for (let i = 0; i < featureTexts.length; i++) {
    const { mesh, initialY } = featureTexts[i];
    const startY = initialY + 0.2;
    mesh.position.y = startY;

    staggerTl.to(
      mesh.position,
      {
        y: initialY,
        duration: 0.5,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
      },
      i * 0.08
    );
  }

  // CTA press
  ctaGroup.userData.handlers = ctaGroup.userData.handlers || {};
  ctaGroup.userData.handlers.click = () => {
    const pressTl = gsap.timeline();
    timelines.push(pressTl);

    pressTl.to(ctaGroup.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
    });

    pressTl.to(
      ctaGroup.scale,
      {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.15,
        ease: 'power2.out',
      },
      0.12
    );

    ctx.emit('navigate', { to: 'hub-pricing' });
  };

  // === CLEANUP ===
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    toDispose.forEach((res) => {
      if (res && res.dispose) res.dispose();
    });
    textMeshes.forEach((text) => {
      if (text.material && text.material.dispose) text.material.dispose();
      if (text.geometry && text.geometry.dispose) text.geometry.dispose();
    });
  };

  return root;
}
